const maxAgeMs = 5 * 60 * 1000
// Small allowance for clock drift between the Convex host and n8n.
const maxClockSkewMs = 60 * 1000

// Constant time: always walks the full length, so timing does not reveal how many characters matched.
const isSameText = (a, b) => {
  if (a.length !== b.length) return false
  let difference = 0
  for (let i = 0; i < a.length; i++) difference |= a.charCodeAt(i) ^ b.charCodeAt(i)

  return difference === 0
}

const received = String($json.headers['x-lendloop-signature'] ?? '')
const expected = $json.expectedSignature

if (typeof expected !== 'string' || expected.length === 0 || !isSameText(received, expected)) {
  return [{ json: { isValid: false } }]
}

// Read from the Webhook node: Crypto drops the binary it hashed. The Webhook node builds this binary inline
// as base64 itself, in every binary data mode (checked with the default and filesystem modes).
const rawBody = Buffer.from($('Webhook').first().binary.data.data, 'base64').toString('utf8')

let payload
try {
  payload = JSON.parse(rawBody)
} catch {
  return [{ json: { isValid: false } }]
}

const knownEvents = ['requested', 'approved', 'declined', 'cancelled', 'returned']

// Checked before the dedupe, so an unknown event is refused and retried, never marked handled.
if (!knownEvents.includes(payload.event)) return [{ json: { isValid: false } }]

const ageMs = Date.now() - Number(payload.sentAt)
const isFresh = ageMs <= maxAgeMs && ageMs >= -maxClockSkewMs

return [{ json: { isValid: isFresh, payload } }]
